}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Profile {
    pub force: u16,
    pub heat: u16,
    pub rate: u16,
    pub quiet: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProfileError {
    EmptyInput,
    MalformedField,
    UnknownField,
    DuplicateField,
    OutOfRange,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Controller {
    limits: Limits,
    profile: Profile,
}

pub fn encode_profile(profile: &Profile) -> String {
    format!(
        "force={};heat={};rate={};quiet={}",
        profile.force,
        profile.heat,
        profile.rate,
        u8::from(profile.quiet)
    )
}

pub fn decode_profile(input: &str) -> Result<Profile, ProfileError> {
    if input.is_empty() {
        return Err(ProfileError::EmptyInput);
    }
    if input.bytes().any(|b| b.is_ascii_whitespace()) {
        return Err(ProfileError::MalformedField);
    }

    let mut values = [0u16; 4];
    let mut seen = [false; 4];
    let mut count = 0;
    for field in input.split(';') {
        if field.is_empty() {
            return Err(ProfileError::MalformedField);
        }
        let (name, raw) = field.split_once('=').ok_or(ProfileError::MalformedField)?;
        if name.is_empty() || raw.is_empty() || raw.contains('=') {
            return Err(ProfileError::MalformedField);
        }
        let index = match name {
            "force" => 0,
            "heat" => 1,
            "rate" => 2,
            "quiet" => 3,
            _ => return Err(ProfileError::UnknownField),
        };
        let value = raw.parse::<u16>().map_err(|_| ProfileError::MalformedField)?;
        if index == 3 && value > 1 {
            return Err(ProfileError::MalformedField);
        }
        seen[index] = true;
        values[index] = value;
        count += 1;
    }
    if count != 4 || seen.iter().any(|present| !present) {
        return Err(ProfileError::MalformedField);
    }
    Ok(Profile {
        force: values[0],
        heat: values[1],
        rate: values[2],
        quiet: values[3] == 1,
    })
}

