    pub fn new(limits: Limits, initial: Profile) -> Result<Self, ProfileError> {
        let controller = Self { limits, profile: initial };
        controller.validate(initial)?;
        Ok(controller)
    }

    fn validate(&self, profile: Profile) -> Result<(), ProfileError> {
        if profile.force > self.limits.max_force
            || profile.heat > self.limits.max_heat
            || profile.rate > self.limits.max_rate
        {
            Err(ProfileError::OutOfRange)
        } else {
            Ok(())
        }
    }

    pub fn profile(&self) -> &Profile {
        &self.profile
    }

    pub fn set_profile(&mut self, requested: Profile) -> Result<(), ProfileError> {
        self.validate(requested)?;
        self.profile = requested;
        Ok(())
    }

    pub fn resume_sequence(&self) -> Vec<String> {
        vec![
            format!("quiet={}", u8::from(self.profile.quiet)),
            format!("force={}", self.profile.force),
            format!("heat={}", self.profile.heat),
            format!("rate={}", self.profile.rate),
        ]
    }
}

