#[path = "solution.rs"]
mod solution;

use solution::{decode_profile, encode_profile, Controller, Limits, Profile, ProfileError};

fn decode(input: &str) -> Profile {
    match decode_profile(input) { Ok(v) => v, Err(_) => panic!("unexpected decode error") }
}

fn assert_profile(p: &Profile, force: u16, heat: u16, rate: u16, quiet: bool) {
    assert_eq!((p.force, p.heat, p.rate, p.quiet), (force, heat, rate, quiet));
}

#[test]
fn decodes_any_order_and_encodes_canonically() {
    let profile = decode("quiet=1;rate=30;force=10;heat=20");
    assert_profile(&profile, 10, 20, 30, true);
    assert_eq!(encode_profile(&profile), "force=10;heat=20;rate=30;quiet=1");

    let zero = decode("force=0;heat=0;rate=0;quiet=0");
    assert_profile(&zero, 0, 0, 0, false);
}

#[test]
fn accepts_full_u16_values_in_text_format() {
    let profile = decode("force=65535;heat=65535;rate=65535;quiet=1");
    assert_eq!(encode_profile(&profile), "force=65535;heat=65535;rate=65535;quiet=1");
}

#[test]
fn empty_input_has_its_specific_error() {
    assert!(matches!(decode_profile(""), Err(ProfileError::EmptyInput)));
}

#[test]
fn duplicate_known_and_unknown_names_have_specific_errors() {
    assert!(matches!(
        decode_profile("force=1;force=2;heat=3;rate=4"),
        Err(ProfileError::DuplicateField)
    ));
    assert!(matches!(
        decode_profile("force=1;heat=2;rate=3;noise=0"),
        Err(ProfileError::UnknownField)
    ));
}

#[test]
fn all_other_text_syntax_failures_are_malformed() {
    let malformed = [
        "force=1;heat=2;rate=3",
        "force=1;heat=2;rate=3;quiet=0;",
        ";force=1;heat=2;rate=3;quiet=0",
        "force=1;;heat=2;rate=3;quiet=0",
        "force=;heat=2;rate=3;quiet=0",
        "force=x;heat=2;rate=3;quiet=0",
        "force=65536;heat=2;rate=3;quiet=0",
        "force=1=2;heat=2;rate=3;quiet=0",
        "force=1;heat=2;rate=3;quiet=2",
        "force=1;heat=2;rate=3;quiet=true",
        "force=1;heat=2;rate=3;quiet= 0",
        "force=1;heat=2;rate=3;quiet=0\n",
    ];
    for input in malformed {
        assert!(matches!(decode_profile(input), Err(ProfileError::MalformedField)), "{input:?}");
    }
}

#[test]
fn controller_enforces_each_limit_inclusively() {
    let initial = Profile { force: 10, heat: 20, rate: 30, quiet: false };
    let controller = Controller::new(Limits { max_force: 10, max_heat: 20, max_rate: 30 }, initial);
    let controller = match controller { Ok(v) => v, Err(_) => panic!("boundary profile should be valid") };
    assert_profile(controller.profile(), 10, 20, 30, false);

    for invalid in [
        Profile { force: 11, heat: 20, rate: 30, quiet: false },
        Profile { force: 10, heat: 21, rate: 30, quiet: false },
        Profile { force: 10, heat: 20, rate: 31, quiet: false },
    ] {
        assert!(matches!(
            Controller::new(Limits { max_force: 10, max_heat: 20, max_rate: 30 }, invalid),
            Err(ProfileError::OutOfRange)
        ));
    }
}

#[test]
fn failed_update_is_atomic_and_successful_update_replaces_profile() {
    let mut controller = match Controller::new(
        Limits { max_force: 5, max_heat: 6, max_rate: 7 },
        Profile { force: 1, heat: 2, rate: 3, quiet: false },
    ) { Ok(v) => v, Err(_) => panic!("unexpected error") };

    assert!(matches!(
        controller.set_profile(Profile { force: 1, heat: 99, rate: 3, quiet: true }),
        Err(ProfileError::OutOfRange)
    ));
    assert_profile(controller.profile(), 1, 2, 3, false);

    assert!(controller.set_profile(Profile { force: 5, heat: 6, rate: 7, quiet: true }).is_ok());
    assert_profile(controller.profile(), 5, 6, 7, true);
}

#[test]
fn resume_commands_are_owned_ordered_and_non_mutating() {
    let controller = match Controller::new(
        Limits { max_force: 100, max_heat: 100, max_rate: 100 },
        Profile { force: 12, heat: 34, rate: 56, quiet: true },
    ) { Ok(v) => v, Err(_) => panic!("unexpected error") };
    let commands = controller.resume_sequence();
    assert_eq!(commands, vec!["quiet=1", "force=12", "heat=34", "rate=56"]);
    assert_profile(controller.profile(), 12, 34, 56, true);
}

